using System.Diagnostics;

namespace GetANNY.Setup.Core;

public sealed record UninstallOptions(string InstallDirectory, bool RemoveAppData);

/// <summary>
/// Orchestrates removal. The NSIS uninstaller generated by electron-builder
/// remains the engine of record: it
/// removes files, shortcuts (incl. AppUserModelId cleanup), the Add/Remove
/// Programs key and — only with --delete-app-data — the per-user app data folders.
///
/// Two entry points:
///   * <see cref="RunInteractiveAsync"/> — the WPF flow with observed stages.
///   * <see cref="RunPassThroughAsync"/> — exact NSIS argument compatibility for
///     QuietUninstallString and for electron-builder's in-place upgrade, which
///     copies the UninstallString target to %TEMP% and runs it with
///     "/S /KEEP_APP_DATA /currentuser [--keep-shortcuts] --updated _?=&lt;dir&gt;".
/// </summary>
public sealed class UninstallService
{
    public static string? LocateInstallDirectory(CommandLine cl)
    {
        if (!string.IsNullOrWhiteSpace(cl.UninstallDirectory) && Directory.Exists(cl.UninstallDirectory))
            return Path.GetFullPath(cl.UninstallDirectory);

        var own = Path.GetDirectoryName(Environment.ProcessPath);
        if (own is not null && Product.FindEngineUninstaller(own) is not null)
            return own;

        var existing = InstallationState.FindExisting();
        if (existing?.InstallLocation is { Length: > 0 } loc && Product.FindEngineUninstaller(loc) is not null)
            return loc;
        return null;
    }

    public async Task RunInteractiveAsync(UninstallOptions options, IProgress<StageUpdate> progress, CancellationToken ct)
    {
        var dir = Path.GetFullPath(options.InstallDirectory);
        var exe = Path.Combine(dir, Product.ExecutableName);
        var engine = Product.FindEngineUninstaller(dir);
        if (engine is null)
            throw new OperationFailedException($"The uninstall engine was not found in {dir}. The installation may already have been removed.");

        // 1 — Close GetANNY (graceful → forceful)
        progress.Report(new StageUpdate(UninstallStages.Close, StageState.Active));
        if (AppProcesses.IsRunning(dir))
        {
            progress.Report(new StageUpdate(UninstallStages.Close, StageState.Active, "Asking GetANNY to exit…"));
            if (!await AppProcesses.CloseAsync(dir, TimeSpan.FromSeconds(8), ct))
                throw new OperationFailedException("GetANNY could not be closed. Close it from the tray and try again.");
            progress.Report(new StageUpdate(UninstallStages.Close, StageState.Done, "Closed"));
        }
        else
        {
            progress.Report(new StageUpdate(UninstallStages.Close, StageState.Done, "Not running"));
        }
        ct.ThrowIfCancellationRequested();

        // 2 — Browser integration (same command installer.nsh runs; flag tells the engine not to repeat it)
        progress.Report(new StageUpdate(UninstallStages.Browser, StageState.Active, "Removing native messaging host registrations…"));
        var hostsDone = false;
        if (File.Exists(exe))
        {
            var code = await RunHelperAsync(exe, "--unregister-browser-hosts --quiet", TimeSpan.FromSeconds(90), ct);
            // Tell NSIS to skip its own cleanup only when the preflight helper
            // actually succeeded. A timeout or non-zero result must leave the
            // fallback enabled, especially while browsers still hold the host.
            hostsDone = code == 0;
            progress.Report(new StageUpdate(UninstallStages.Browser, StageState.Done,
                code == 0 ? "Registrations removed" : code is null ? "Helper unavailable; engine will retry" : $"Helper exited with code {code}; engine will retry"));
        }
        else
        {
            progress.Report(new StageUpdate(UninstallStages.Browser, StageState.Skipped, "Application executable missing"));
        }
        ct.ThrowIfCancellationRequested();

        // 3/4/5(/6) — Engine
        var switches = new List<string> { "/S", "/currentuser" };
        if (hostsDone) switches.Add("--hosts-unregistered");
        if (options.RemoveAppData) switches.Add("--delete-app-data");
        else progress.Report(new StageUpdate(UninstallStages.Data, StageState.Skipped, "Kept — history, settings, database and downloads are untouched"));

        var tempEngine = Path.Combine(Path.GetTempPath(), $"GetANNY-Uninstall-{Environment.ProcessId}.exe");
        File.Copy(engine, tempEngine, true);
        try
        {
            progress.Report(new StageUpdate(UninstallStages.Files, StageState.Active, "Removing files from " + dir));
            using var observerCts = CancellationTokenSource.CreateLinkedTokenSource(ct);
            var observer = ObserveAsync(exe, progress, observerCts.Token);
            var result = await NsisEngine.RunAsync(tempEngine, CommandLine.BuildEngineArguments(switches, "_?=", dir), Path.GetTempPath(), CancellationToken.None, TimeSpan.FromMinutes(10));
            observerCts.Cancel();
            try { await observer; } catch (OperationCanceledException) { }

            if (!result.Succeeded) throw new OperationFailedException(NsisEngine.Describe(result.ExitCode));

            progress.Report(new StageUpdate(UninstallStages.Files, File.Exists(exe) ? StageState.Failed : StageState.Done));
            var leftoverLinks = Shortcuts.FindAll().Where(l => !LinkTargetsElsewhere(l, dir)).ToList();
            progress.Report(new StageUpdate(UninstallStages.Shortcuts, leftoverLinks.Count == 0 ? StageState.Done : StageState.Failed,
                leftoverLinks.Count == 0 ? null : $"{leftoverLinks.Count} shortcut(s) remain"));
            progress.Report(new StageUpdate(UninstallStages.Registry, InstallationState.UninstallKeyExists() ? StageState.Failed : StageState.Done));
            if (options.RemoveAppData)
            {
                RemoveOwnedAppData();
                var gone = !Directory.Exists(Product.UserDataDirectory) && !Directory.Exists(Product.ProductDataDirectory);
                progress.Report(new StageUpdate(UninstallStages.Data, gone ? StageState.Done : StageState.Failed, gone ? "Removed" : "Some files were in use"));
                if (!gone) throw new OperationFailedException("GetANNY was uninstalled, but some application data files are still in use. Close GetANNY and try removing its data again.");
            }
        }
        finally
        {
            try { File.Delete(tempEngine); } catch (IOException) { } catch (UnauthorizedAccessException) { }
        }

        // 7 — Finish: remove whatever the engine could not (our own running EXE, the now-empty folder)
        progress.Report(new StageUpdate(UninstallStages.Finish, StageState.Active));
        ScheduleSelfDelete(dir);
        progress.Report(new StageUpdate(UninstallStages.Finish, StageState.Done));
    }

    /// <summary>Silent, argument-compatible delegate to the NSIS uninstaller. Returns its exit code.</summary>
    public async Task<int> RunPassThroughAsync(CommandLine cl)
    {
        var dir = LocateInstallDirectory(cl);
        if (dir is null) { SetupLog.Error("pass-through: install directory not found"); return 2; }
        var engine = Product.FindEngineUninstaller(dir);
        if (engine is null) { SetupLog.Error("pass-through: engine missing in " + dir); return 2; }

        var switches = cl.Switches.ToList();
        if (!cl.IsSilent) switches.Insert(0, "/S");
        if (!cl.IsCurrentUser && !cl.IsAllUsers) switches.Add("/currentuser");

        var tempEngine = Path.Combine(Path.GetTempPath(), $"GetANNY-Uninstall-{Environment.ProcessId}.exe");
        File.Copy(engine, tempEngine, true);
        try
        {
            var result = await NsisEngine.RunAsync(tempEngine, CommandLine.BuildEngineArguments(switches, "_?=", dir), Path.GetTempPath(), CancellationToken.None, TimeSpan.FromMinutes(10));
            if (result.Succeeded && cl.IsDeleteAppData && !cl.IsUpdated)
                RemoveOwnedAppData();
            if (result.Succeeded && !cl.IsUpdated) ScheduleSelfDelete(dir);
            return result.TimedOut ? 2 : result.ExitCode;
        }
        finally
        {
            try { File.Delete(tempEngine); } catch (IOException) { } catch (UnauthorizedAccessException) { }
        }
    }

    /// <summary>
    /// Removes only GetANNY's known per-user Electron data roots. This runs only
    /// after explicit opt-in; downloads and the selected install directory are
    /// never recursively removed by the shell.
    /// </summary>
    private static void RemoveOwnedAppData()
    {
        foreach (var directory in new[] { Product.UserDataDirectory, Product.ProductDataDirectory }.Distinct(StringComparer.OrdinalIgnoreCase))
        {
            if (!Directory.Exists(directory)) continue;
            Directory.Delete(directory, recursive: true);
        }
    }

    private static async Task ObserveAsync(string exe, IProgress<StageUpdate> progress, CancellationToken ct)
    {
        bool files = false, links = false;
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(250, ct);
            if (!files && !File.Exists(exe))
            {
                files = true;
                progress.Report(new StageUpdate(UninstallStages.Files, StageState.Done));
                progress.Report(new StageUpdate(UninstallStages.Shortcuts, StageState.Active));
            }
            if (files && !links && !Shortcuts.DesktopExists && !Shortcuts.StartMenuExists)
            {
                links = true;
                progress.Report(new StageUpdate(UninstallStages.Shortcuts, StageState.Done));
                progress.Report(new StageUpdate(UninstallStages.Registry, StageState.Active));
            }
        }
    }

    private static async Task<int?> RunHelperAsync(string exe, string args, TimeSpan timeout, CancellationToken ct)
    {
        try
        {
            var psi = new ProcessStartInfo(exe, args) { UseShellExecute = false, CreateNoWindow = true, WorkingDirectory = Path.GetDirectoryName(exe)! };
            using var p = Process.Start(psi);
            if (p is null) return null;
            using var cts = CancellationTokenSource.CreateLinkedTokenSource(ct);
            cts.CancelAfter(timeout);
            try { await p.WaitForExitAsync(cts.Token); }
            catch (OperationCanceledException) when (!ct.IsCancellationRequested)
            {
                try { p.Kill(true); } catch (InvalidOperationException) { }
                return 1;
            }
            SetupLog.Info($"helper {args} exit {p.ExitCode}");
            return p.ExitCode;
        }
        catch (System.ComponentModel.Win32Exception ex) { SetupLog.Warn("helper failed: " + ex.Message); return null; }
    }

    private static bool LinkTargetsElsewhere(string lnk, string dir)
    {
        // Links the engine owns were deleted; anything left that still points into
        // the install directory counts as a leftover. Others belong to other installs.
        try
        {
            var bytes = File.ReadAllBytes(lnk);
            var text = System.Text.Encoding.Unicode.GetString(bytes) + System.Text.Encoding.Default.GetString(bytes);
            return !text.Contains(dir, StringComparison.OrdinalIgnoreCase);
        }
        catch (IOException) { return true; }
    }

    /// <summary>
    /// A running EXE cannot delete itself. When we run from the install directory,
    /// a detached cmd.exe retries the delete after we exit and then removes the
    /// (now empty) folder — non-recursively, so a user-chosen shared folder is safe.
    /// </summary>
    private static void ScheduleSelfDelete(string installDir)
    {
        var self = Environment.ProcessPath;
        if (self is null) return;
        var inside = Path.GetFullPath(self).StartsWith(installDir.TrimEnd('\\') + "\\", StringComparison.OrdinalIgnoreCase);
        var script = Path.Combine(Path.GetTempPath(), $"getanny-cleanup-{Environment.ProcessId}.cmd");
        var exeArg = inside ? self : string.Empty;
        File.WriteAllText(script,
            "@echo off\r\n" +
            "set \"exe=%~1\"\r\n" +
            "set \"dir=%~2\"\r\n" +
            "if \"%exe%\"==\"\" goto folder\r\n" +
            "for /l %%i in (1,1,60) do (\r\n" +
            "  if not exist \"%exe%\" goto folder\r\n" +
            "  del /f /q \"%exe%\" >nul 2>&1\r\n" +
            "  if exist \"%exe%\" timeout /t 1 /nobreak >nul\r\n" +
            ")\r\n" +
            ":folder\r\n" +
            "rmdir \"%dir%\" >nul 2>&1\r\n" +
            "del /f /q \"%~f0\" >nul 2>&1\r\n");
        var psi = new ProcessStartInfo("cmd.exe", $"/d /c \"\"{script}\" \"{exeArg}\" \"{installDir}\"\"")
        {
            UseShellExecute = false,
            CreateNoWindow = true,
            WindowStyle = ProcessWindowStyle.Hidden,
            WorkingDirectory = Path.GetTempPath(),
        };
        SetupLog.Info("scheduled cleanup: " + psi.Arguments);
        using var _ = Process.Start(psi);
    }
}
